def get_standard_by_row_index(row_index: int):
    for std in AUDIT_STANDARDS:
        if std["row_index"] == row_index:
            return std
    return None

def get_standard_options():
    """Return a list of (row_index, display_label) tuples for dropdown selection."""
    options = []
    for std in AUDIT_STANDARDS:
        label = f"Row {std['row_index']}: {std['section'][:30]}... | {std['display_name']} ({std['fsp_ref']})"
        options.append((std["row_index"], label))
    return options

def match_standard_by_keywords(text: str) -> int:
    """Heuristic standard matcher given observation or note keywords."""
    text_lower = text.lower()
    
    # 1. Cleanliness / Cleaning (Row 32)
    if any(k in text_lower for k in ["dirty", "clean", "grease", "grime", "dust", "residue", "spill", "splash", "canopy", "microwave", "oven", "toaster", "sink grime"]):
        return 32
        
    # 2. Fixtures, fittings and equipment (Row 53)
    if any(k in text_lower for k in ["broken", "damaged", "timber", "silicone", "mould", "mold", "seal", "coving", "crack", "rust", "deteriorated", "door", "hinge", "fixture"]):
        return 53
        
    # 3. Floors (Row 50)
    if any(k in text_lower for k in ["floor", "coving", "drain", "tile", "grout"]):
        return 50
        
    # 4. Walls and Ceilings (Row 51)
    if any(k in text_lower for k in ["wall", "ceiling", "peeling paint"]):
        return 51
        
    # 5. Food handling skills / training (Row 8)
    if any(k in text_lower for k in ["basin obstructed", "hand wash obstructed", "misuse of container", "uncovered food", "scoop in food", "floor contact", "date label", "use-by", "expired"]):
        return 8
        
    # 6. Cold Storage / Cool room / Freezer (Row 14)
    if any(k in text_lower for k in ["cool room", "coolroom", "refrigerator", "freezer", "fridge", "chiller"]):
        return 14
        
    # 7. Dry Storage (Row 13)
    if any(k in text_lower for k in ["dry store", "dry storage", "pantry", "shelving"]):
        return 13
        
    # 8. Sanitising / Dishwasher (Row 33 or 34)
    if any(k in text_lower for k in ["dishwasher", "rinse temp"]):
        return 34
    if any(k in text_lower for k in ["sanitiser", "sanitizer", "chemical"]):
        return 33
        
    # 9. Temperature measuring devices (Row 37)
    if any(k in text_lower for k in ["thermometer", "probe", "gauge", "calibration"]):
        return 37
        
    # 10. Animals and Pests (Row 38)
    if any(k in text_lower for k in ["pest", "rodent", "insect", "droppings", "fly", "cockroach"]):
        return 38
        
    # 11. Maintenance (Row 35)
    if any(k in text_lower for k in ["maintenance", "repair needed"]):
        return 35
        
    # Default to 32 (Cleanliness)
    return 32
